def add_binary(a, b):
    i, j = len(a)-1, len(b)-1
    carry = 0; out = []
    while i >= 0 or j >= 0 or carry:
        s = carry
        if i >= 0: s += int(a[i]); i -= 1
        if j >= 0: s += int(b[j]); j -= 1
        out.append(str(s % 2)); carry = s // 2
    return ''.join(reversed(out))

def reverse_bits(n):
    res = 0
    for _ in range(32):
        res = (res << 1) | (n & 1)
        n >>= 1
    return res

def hamming_weight(n):
    cnt = 0
    while n:
        n &= n - 1
        cnt += 1
    return cnt

