def single_number(nums):
    res = 0
    for i in range(32):
        s = sum((x >> i) & 1 for x in nums) % 3
        res |= s << i
    return res - (1 << 32) if res >= (1 << 31) else res

from collections import Counter
def single_number(nums):
    return next(x for x, c in Counter(nums).items() if c == 1)

def range_bitwise_and(left, right):
        sh = 0
        while left != right:
            left >>= 1; right >>= 1; sh += 1
        return left << sh

